1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	};
11	
12	/** Initial assessment surcharge on a customer's first insurance. */
13	const FIRST_INSURANCE_RATE = 0.1;
14	
15	export type Scenario = {
16	  customer: { yearsWithMHPCO: number };
17	  steps: Step[];
18	};
19	
20	export type Step = {
21	  op: string;
22	  items: Item[];
23	};
24	
25	export type Item = { type: string } & Record<string, unknown>;
26	
27	export type Result = { premium: number };
28	
29	export type ScenarioOutcome = { results: Result[] };
30	
31	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
32	  const items = scenario.steps[0].items;
33	  const policyBasePremium = items.reduce(
34	    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type],
35	    0,
36	  );
37	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
38	  return {
39	    results: [
40	      { premium: policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE },
41	    ],
42	  };
43	};
